---APPLIED---
SURVIVING_NEIGHBOR_COUNTS = (2, 3)
NEIGHBORS_REQUIRED_FOR_BIRTH = 3


def next_generation(living_cells):
    survivors = [
        cell
        for cell in living_cells
        if survives(count_living_neighbors(cell, living_cells))
    ]
    newborns = [
        cell
        for cell in dead_neighbors_of(living_cells)
        if is_born(count_living_neighbors(cell, living_cells))
    ]
    return survivors + newborns


def survives(living_neighbor_count):
    return living_neighbor_count in SURVIVING_NEIGHBOR_COUNTS


def is_born(living_neighbor_count):
    return living_neighbor_count == NEIGHBORS_REQUIRED_FOR_BIRTH


def dead_neighbors_of(living_cells):
    return {
        neighbor
        for cell in living_cells
        for neighbor in neighbors_of(cell)
        if neighbor not in living_cells
    }


def count_living_neighbors(cell, living_cells):
    return len([neighbor for neighbor in neighbors_of(cell) if neighbor in living_cells])


def neighbors_of(cell):
    x, y = cell
    return [
        (x + dx, y + dy)
        for dx in (-1, 0, 1)
        for dy in (-1, 0, 1)
        if (dx, dy) != (0, 0)
    ]
